DO $seed$
DECLARE author_id BIGINT;
BEGIN
  SELECT id INTO author_id FROM users WHERE email='system@fintalent.local' AND is_system LIMIT 1;
  IF author_id IS NULL THEN RETURN; END IF;

  ON CONFLICT(slug) DO UPDATE SET type=EXCLUDED.type,status='PUBLISHED',title=EXCLUDED.title,short_description=EXCLUDED.short_description,description=EXCLUDED.description,cover_image=EXCLUDED.cover_image,price=EXCLUDED.price,old_price=EXCLUDED.old_price,tags=EXCLUDED.tags,topics=EXCLUDED.topics,audiences=EXCLUDED.audiences,product_data=EXCLUDED.product_data,published_at=COALESCE(profimarket_solutions.published_at,NOW()),deleted_at=NULL;

  DELETE FROM profimarket_media WHERE solution_id IN (SELECT id FROM profimarket_solutions WHERE slug IN ('peredacha-dokumentov-finkoper-1c','kontrol-nezakrytyh-operaciy-1c','finansovaya-model-buhgalterskoy-kompanii','zakrytie-mesyaca-bez-oshibok'));
  SELECT id,'IMAGE','/static/profimarket-ai-publish.png',10,TRUE FROM profimarket_solutions WHERE slug IN ('peredacha-dokumentov-finkoper-1c','kontrol-nezakrytyh-operaciy-1c','finansovaya-model-buhgalterskoy-kompanii','zakrytie-mesyaca-bez-oshibok');
  UPDATE profimarket_solutions SET product_data=product_data||'{"video_url":"https://rutube.ru/video/594df793ea907f3a7a4b04a34a33f13a/"}'::jsonb WHERE slug='peredacha-dokumentov-finkoper-1c';
END $seed$;
