  VALUES
  (author_id,'AUTOMATION','PUBLISHED','Автоматический контроль требований ФНС','avtomaticheskiy-kontrol-trebovaniy-fns','Получает новые требования, создаёт задачу ответственному и контролирует срок ответа.','Готовый сценарий для бухгалтерской компании: фиксирует входящее требование, извлекает срок, назначает ответственного и напоминает о контрольной дате.','/static/profimarket-hero.png',14900,17900,'ONE_TIME',ARRAY['ФНС','уведомления','задачи'],ARRAY['Отчётность','Автоматизация'],ARRAY['Бухгалтерские компании'],TRUE,TRUE,NOW()-INTERVAL '1 day','{"category":"Отчетность","process":"Контроль новых требований ФНС и сроков ответа без ручного ведения таблиц.","trigger":"Получено новое требование ФНС","result":"Создана задача, назначен ответственный и настроены напоминания.","before":"Сотрудник вручную проверяет требования и переносит сроки в таблицу.","after":"Требование автоматически превращается в контролируемую задачу.","steps":["Получаем требование","Определяем срок ответа","Создаём задачу","Отправляем уведомление"],"compatibility":["1С","FinKoper","Email","Telegram","API"],"complexity":"Просто","implementation_time":"1–2 часа","requires_services":"Почта и Telegram","requires_api":true,"requires_installation":true,"included":["Готовый сценарий","Инструкция по установке","Шаблоны уведомлений","Помощь автора при запуске"],"installation_help":true,"installation_guide":true,"demo_example":"Письмо с требованием превращается в задачу со сроком и ответственным."}'::jsonb),
  (author_id,'AUTOMATION','PUBLISHED','Автоматическая загрузка банковских выписок','avtomaticheskaya-zagruzka-bankovskih-vypisok','Загружает банковские выписки, проверяет дубли и формирует отчёт об обработке.','Сценарий сокращает ежедневную ручную работу с выписками и помогает контролировать ошибки загрузки.','/static/images/profimarket-preview-publish.png',9900,NULL,'ONE_TIME',ARRAY['банк','1С','выписки'],ARRAY['Банки'],ARRAY['Бухгалтеры'],FALSE,TRUE,NOW()-INTERVAL '3 days','{"category":"Банки","process":"Получение и загрузка выписок по расписанию.","trigger":"Наступило время плановой загрузки","result":"Выписки загружены, дубли исключены, отчёт отправлен.","before":"Бухгалтер скачивает файлы из каждого банка вручную.","after":"Все выписки загружаются автоматически до начала рабочего дня.","steps":["Подключаем банки","Получаем выписки","Проверяем дубли","Загружаем в 1С","Формируем отчёт"],"compatibility":["1С","Excel","Email","API"],"complexity":"Требуются базовые технические знания","implementation_time":"3–4 часа","included":["Сценарий автоматизации","Настройка расписания","Журнал ошибок","Инструкция"],"installation_guide":true}'::jsonb),
  (author_id,'INSTRUCTION','PUBLISHED','Как отвечать на требования ФНС: пошаговая инструкция','kak-otvechat-na-trebovaniya-fns','Практический порядок разбора требования, подготовки документов и отправки ответа.','Инструкция помогает быстро определить предмет требования, проверить сроки и подготовить аргументированный ответ.','/static/images/profimarket-preview-publish.png',3900,4900,'ONE_TIME',ARRAY['ФНС','налоги','инструкция'],ARRAY['Налоги'],ARRAY['Бухгалтеры','Налоговые консультанты'],TRUE,TRUE,NOW()-INTERVAL '2 days','{"theme":"Требования ФНС","page_count":28,"format":"PDF","updated_at":"12.09.2026","contents":["Первичная проверка требования","Какие документы собрать","Подготовка пояснений","Отправка через ТКС","Контроль результата","Типичные ошибки"],"excerpt_title":"Шаг 2. Определите предмет требования","excerpt":"Сначала сопоставьте указанные в требовании декларации, периоды и контрольные соотношения. Проверьте, относится ли расхождение к данным текущего периода или связано с уточнённой декларацией. Зафиксируйте крайний срок ответа и перечень запрошенных документов.","included":["Инструкция в PDF","Чек-лист проверки ответа","Шаблон пояснения","Таблица контроля сроков"],"delivery_files":[{"format":"PDF","planned":true}]}'::jsonb),
  (author_id,'INSTRUCTION','PUBLISHED','Приём нового бухгалтерского клиента','priem-novogo-buhgalterskogo-klienta-instrukciya','Полная инструкция от первичного аудита до передачи базы в работу.','Последовательность действий, документов и контрольных точек для безопасного запуска обслуживания нового клиента.','/static/profimarket-hero.png',4500,NULL,'ONE_TIME',ARRAY['клиенты','онбординг'],ARRAY['Клиенты'],ARRAY['Руководители','Главные бухгалтеры'],FALSE,TRUE,NOW()-INTERVAL '5 days','{"theme":"Работа с клиентами","page_count":34,"format":"PDF · DOCX","updated_at":"05.09.2026","contents":["Предварительная оценка","Запрос документов","Аудит базы","Фиксация рисков","Настройка коммуникаций","Первый отчётный период"],"excerpt_title":"Первичный аудит базы","excerpt":"До подписания акта приёма зафиксируйте состояние учёта: закрытые периоды, незавершённые операции, расхождения по налогам и отсутствие первичных документов. Результаты оформите отдельным приложением.","included":["Инструкция","Акт приёма базы","Список документов","Карта рисков"]}'::jsonb),
  (author_id,'ONEC_INTEGRATION','PUBLISHED','Автоматическая передача документов из FinKoper в 1С','peredacha-dokumentov-finkoper-1c','Интеграционный модуль для передачи документов и статусов обработки в 1С.','Коннектор синхронизирует документы, контрагентов и результаты обработки без ручного импорта.','/static/profimarket-hero.png',24900,29900,'ONE_TIME',ARRAY['1С','FinKoper','интеграция'],ARRAY['Интеграции'],ARRAY['Бухгалтерские компании'],TRUE,TRUE,NOW()-INTERVAL '1 day','{"solution_type":"Интеграция","configurations":["1С:Бухгалтерия предприятия","1С:УНФ"],"configuration_version":"3.0+","platform_version":"8.3.24+","database_modes":["Файловая","Серверная"],"changes_configuration":false,"http_services":true,"external_api":true,"features":["Передаёт документы и файлы","Синхронизирует контрагентов","Работает по расписанию","Ведёт журнал ошибок","Возвращает статус обработки"],"how_works":"Модуль обращается к API FinKoper, получает новые документы и создаёт соответствующие объекты в 1С.","installation_steps":["Подключение расширения","Публикация HTTP-сервиса","Настройка ключа API","Проверка обмена"],"installation_included":true,"setup_included":true,"updates_included":true,"support":"3 месяца технической поддержки","included":["Расширение 1С","Модуль обмена","Инструкция","Первичная настройка"]}'::jsonb),
  (author_id,'ONEC_INTEGRATION','PUBLISHED','Контроль незакрытых операций в 1С:Бухгалтерии','kontrol-nezakrytyh-operaciy-1c','Отчёт находит незавершённые операции и помогает закрыть месяц без пропусков.','Внешний отчёт собирает контрольные точки закрытия месяца в одном окне.','/static/images/profimarket-preview-publish.png',7900,NULL,'ONE_TIME',ARRAY['1С','закрытие месяца'],ARRAY['Отчёты'],ARRAY['Главные бухгалтеры'],FALSE,TRUE,NOW()-INTERVAL '4 days','{"solution_type":"Отчет","configurations":["1С:Бухгалтерия предприятия"],"configuration_version":"3.0","platform_version":"8.3.22+","database_modes":["Файловая","Серверная"],"features":["Проверяет незакрытые документы","Находит отрицательные остатки","Контролирует регламентные операции","Формирует список ответственных"],"how_works":"Отчёт анализирует документы и регистры выбранного периода и группирует замечания по участкам учёта.","installation_steps":["Открыть внешнюю обработку","Добавить в дополнительные отчёты","Настроить права"],"installation_included":false,"support":"Обновления в течение года","included":["Файл отчёта","Инструкция","Набор контрольных правил"]}'::jsonb),
  (author_id,'TEMPLATE','PUBLISHED','Финансовая модель бухгалтерской компании','finansovaya-model-buhgalterskoy-kompanii','Excel-модель для планирования выручки, загрузки команды и прибыли.','Рабочая модель с формулами, сценариями роста и наглядным dashboard для руководителя.','/static/images/profimarket-preview-publish.png',5900,6900,'ONE_TIME',ARRAY['Excel','финмодель'],ARRAY['Финансы'],ARRAY['Руководители'],TRUE,TRUE,NOW()-INTERVAL '2 days','{"category":"Финансовое планирование","file_type":"Excel","editable":true,"use_case":"Планирование экономики бухгалтерской компании и оценка рентабельности команды.","contents":["План продаж","Расчёт загрузки сотрудников","Фонд оплаты труда","P&L","Движение денег","Dashboard"],"fragment":"В демонстрационном листе показаны выручка по тарифам, прямые затраты, маржинальность и точка безубыточности.","structure":"6 связанных листов · автоматические формулы · три сценария","features":["Сценарный анализ","Автоматические формулы","Графики план/факт","Подсветка отклонений"],"included":["Excel-файл","Пример заполнения","Видеоинструкция"],"delivery_files":[{"format":"XLSX","planned":true}]}'::jsonb),
